\set ON_ERROR_STOP on
begin;
create schema test;
create table test.state(key text primary key,value jsonb);
grant usage on schema test to anon,authenticated;
grant select,insert,update on test.state to anon,authenticated;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$
begin if condition is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test.denied(statement text,label text) returns void language plpgsql as $$
begin
 begin execute statement; exception when others then raise notice 'PASS: % (rejected)',label; return; end;
 raise exception 'FAIL: % was allowed',label;
end $$;
grant execute on all functions in schema test to anon,authenticated;
select test.ok((select count(*)=2 from public.classes),'exactly two mandatory classes');
-- The seed can safely be rerun without duplicating classes.
insert into public.classes(name,slug) values('Poraquê','poraque'),('Pitiú','pitiu') on conflict(slug) do update set name=excluded.name;
select test.ok((select array_agg(name order by slug)=array['Pitiú','Poraquê'] from public.classes),'idempotent real class names');
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into public.admin_users values('00000000-0000-0000-0000-000000000001','admin',now()),('00000000-0000-0000-0000-000000000002','teacher',now());
set local role anon;
insert into test.state values('team',public.register_team((select id from public.classes where slug='poraque'),' Os Hackers ','Ana Silva','João Souza'));
select test.ok((select value ? 'credential' and value ? 'token' from test.state where key='team'),'atomic registration returns private credential and session');
select test.ok(public.register_team((select id from public.classes where slug='poraque'),'os hackers','Ana Silva','João Souza') ? 'error','normalized duplicate team name rejected');
insert into test.state values('other',public.register_team((select id from public.classes where slug='pitiu'),'OS HACKERS','Maria Silva','José Souza'));
select test.ok((select value ? 'team_id' from test.state where key='other'),'same name in another class allowed');
select test.ok(public.register_team((select id from public.classes where slug='poraque'),'Incomplete','Ana Silva','') ? 'error','invalid second member rejected');
select test.denied('select full_name from public.team_members','anonymous cannot read student names');
select test.denied('select * from public.grades','anonymous cannot read grades');
select test.denied('select * from public.teams','anonymous cannot read credential hashes');
select test.denied('select * from public.answers','anonymous cannot read responses');
select test.denied('insert into public.public_leaderboard(team_id,class_id,public_name,points) values(gen_random_uuid(),gen_random_uuid(),''Cheat'',999)','anonymous cannot write ranking');
select test.denied('update public.grades set points=999','anonymous cannot update grades');
select test.denied('select app_private.new_session(gen_random_uuid())','anonymous cannot call private helpers');
select test.denied('select public.team_history(repeat(''0'',64))','forged bearer rejected');
select test.ok((select points=0 and solved_count=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'new team immediately ranked at zero');
insert into test.state select 'return',public.login_team(value->>'access_code',value->>'credential') from test.state where key='team';
select test.ok((select value->>'team_id'=(select value->>'team_id' from test.state where key='team') from test.state where key='return'),'Live Boot return reuses stable team UUID without local state');
reset role;
set constraints all immediate;
set constraints all deferred;
select test.ok((select count(*)=4 from public.team_members),'exactly two members persisted per team');
select test.ok((select count(*)=2 from public.teams),'invalid registration left no team or member');
select test.ok((select credential_hash<>s.value->>'credential' and credential_hash like '$2a$%' from public.teams t join test.state s on t.id=(s.value->>'team_id')::uuid where s.key='team'),'credential stored as bcrypt hash');
select test.ok((select count(*)=3 from app_private.team_sessions),'only hashed bearer sessions persisted');
select test.ok((select bool_and(length(token_hash)=64) from app_private.team_sessions),'session tokens stored as SHA256 hashes');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select test.ok((select count(*)=0 from public.grades),'Auth account alone cannot read grades');
select test.ok((select count(*)=0 from public.team_members),'Auth account alone cannot read names');
select test.denied('select public.rotate_team_credential(gen_random_uuid())','Auth account alone cannot reset credentials');
select test.denied('select public.save_activity(''Hack'', '''', array[]::uuid[], ''[]'')','Auth account alone cannot create activities');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into test.state values('activity1',to_jsonb(public.save_activity('Atividade 1','Teste real',array[(select id from public.classes where slug='poraque')],
 '[{"prompt":"2 + 2?","kind":"multiple_choice","points":10,"options":[{"label":"4","is_correct":true},{"label":"5","is_correct":false}]},{"prompt":"Linux é um sistema operacional?","kind":"true_false","points":5,"options":[{"label":"Verdadeiro","is_correct":true},{"label":"Falso","is_correct":false}]}]'::jsonb,true)));
insert into test.state values('activity2',to_jsonb(public.save_activity('Atividade 2','Outra atividade',array[(select id from public.classes where slug='poraque'),(select id from public.classes where slug='pitiu')],
 '[{"prompt":"Segunda atividade?","kind":"true_false","points":7,"options":[{"label":"Verdadeiro","is_correct":true},{"label":"Falso","is_correct":false}]}]'::jsonb,false)));
insert into test.state select 'session1',to_jsonb(id) from public.activity_sessions where activity_id=(select (value#>>'{}')::uuid from test.state where key='activity1');
insert into test.state select 'session2',to_jsonb(id) from public.activity_sessions where activity_id=(select (value#>>'{}')::uuid from test.state where key='activity2');
select test.ok(public.public_activity((select (value#>>'{}')::uuid from test.state where key='session1')) ? 'error','draft activity is not public');
select public.set_session_publication((select (value#>>'{}')::uuid from test.state where key='session1'),true);
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session1'),'open');
select public.set_session_publication((select (value#>>'{}')::uuid from test.state where key='session2'),true);
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session2'),'open');
insert into test.state select 'answers1',jsonb_agg(jsonb_build_object('question_id',q.id,'option_id',o.id)) from public.questions q join public.question_options o on o.question_id=q.id and o.is_correct where q.activity_id=(select (value#>>'{}')::uuid from test.state where key='activity1');
insert into test.state select 'answers2',jsonb_agg(jsonb_build_object('question_id',q.id,'option_id',o.id)) from public.questions q join public.question_options o on o.question_id=q.id and o.is_correct where q.activity_id=(select (value#>>'{}')::uuid from test.state where key='activity2');
select test.ok((select count(*)=4 from public.team_members),'authorized staff can privately read names');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select test.ok(not (public.public_activity((select (value#>>'{}')::uuid from test.state where key='session1'))::text like '%is_correct%'),'public questions never include answer key');
select test.denied($q$select public.join_activity((select value->>'token' from test.state where key='other'),(select (value#>>'{}')::uuid from test.state where key='session1'))$q$,'wrong class cannot join session');
insert into test.state select 'attempt1',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session1'));
select test.ok(public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session1'))->>'attempt_id'=(select value->>'attempt_id' from test.state where key='attempt1'),'joining twice returns same open attempt');
select test.denied($q$select public.submit_attempt((select value->>'token' from test.state where key='other'),(select (value->>'attempt_id')::uuid from test.state where key='attempt1'),(select value from test.state where key='answers1'))$q$,'other team cannot submit an attempt');
select test.denied($q$select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt1'),'[]')$q$,'incomplete answers rejected');
select test.denied($q$select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt1'),jsonb_build_array((select value->0 from test.state where key='answers1'),(select value->0 from test.state where key='answers1')))$q$,'duplicate question answers rejected');
select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt1'),(select value from test.state where key='answers1'));
select test.ok(public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt1'),(select value from test.state where key='answers1'))->>'already_submitted'='true','duplicate delivery acknowledged without creating new answers');
select test.ok(public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session1'))->>'submitted'='true','completed attempt reused until explicit retry authorization');
insert into test.state select 'attempt2',public.join_activity((select value->>'token' from test.state where key='return'),(select (value#>>'{}')::uuid from test.state where key='session2'));
select public.submit_attempt((select value->>'token' from test.state where key='return'),(select (value->>'attempt_id')::uuid from test.state where key='attempt2'),(select value from test.state where key='answers2'));
select test.ok((select jsonb_array_length(public.team_history(value->>'token')->'attempts')=2 from test.state where key='team'),'same permanent team participates in multiple activities');
select test.ok((select points=0 and solved_count=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'assessment grading never changes public CTF ranking');
reset role;
select test.ok((select count(*)=2 from public.grades),'both pedagogical grades persist');
select test.ok((select count(*)=2 from public.attempts where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'history remains tied to original team');
select test.ok((select bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'RLS enabled on all exposed tables');
select test.ok(exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='public_leaderboard'),'sanitized ranking registered in Realtime publication');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select test.ok((select count(*)=2 from public.grades),'explicitly authorized teacher can read grades');
select test.denied($q$select public.rotate_team_credential((select (value->>'team_id')::uuid from test.state where key='team'))$q$,'teacher cannot rotate private credentials');
select public.adjust_grade((select (value->>'attempt_id')::uuid from test.state where key='attempt1'),12,'Correção pedagógica');
select test.ok((select points=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'pedagogical grade correction does not change CTF');
select test.denied($q$select public.adjust_grade((select (value->>'attempt_id')::uuid from test.state where key='attempt1'),999,'Invalid')$q$,'grade cannot exceed maximum');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.authorize_retry((select (value->>'attempt_id')::uuid from test.state where key='attempt1'));
set local role anon;
insert into test.state select 'retry',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session1'));
select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='retry'),(select value from test.state where key='answers1'));
select test.ok((select points=0 and solved_count=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'authorized retry preserves history without farming CTF points');
-- Invalid credential attempts return JSON rather than raising, so limiter writes commit.
do $$ begin for i in 1..10 loop perform public.login_team((select value->>'access_code' from test.state where key='team'),repeat('0',48)); end loop; end $$;
select test.ok(public.login_team((select value->>'access_code' from test.state where key='team'),(select value->>'credential' from test.state where key='team'))->>'error' like 'Muitas tentativas%','failed login counter survives rejected credentials');
set local role authenticated;
insert into test.state select 'rotated',public.rotate_team_credential((value->>'team_id')::uuid) from test.state where key='team';
set local role anon;
select test.denied($q$select public.team_history((select value->>'token' from test.state where key='team'))$q$,'rotation revokes old bearer sessions');
select test.ok(public.login_team((select value->>'access_code' from test.state where key='team'),(select value->>'credential' from test.state where key='team')) ? 'error','old private credential no longer works');
insert into test.state select 'recovered',public.login_team(value->>'access_code',value->>'credential') from test.state where key='rotated';
select test.ok((select value->>'team_id'=(select value->>'team_id' from test.state where key='team') from test.state where key='recovered'),'new credential restores the original permanent team');
select test.ok((select jsonb_array_length(public.team_history(value->>'token')->'attempts')=3 from test.state where key='recovered'),'recovered team retains all participation history');
reset role;
-- Admin rotation should clear the failed-login lock as well.
select test.ok((select count(*)=3 from public.grades),'credential recovery preserves all grades and attempts');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.adjust_ctf('00000000-0000-0000-0000-000000000099',(select (value->>'team_id')::uuid from test.state where key='team'),3,'Ajuste do administrador');
select public.adjust_ctf('00000000-0000-0000-0000-000000000099',(select (value->>'team_id')::uuid from test.state where key='team'),3,'Reenvio idempotente');
select test.ok((select points=3 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'manual CTF adjustment is idempotent');
select test.ok((select points=12 from public.grades where attempt_id=(select (value->>'attempt_id')::uuid from test.state where key='attempt1')),'CTF adjustments do not alter private grades');
-- Retiring publication must not unlock historical question content.
select public.set_session_publication((select (value#>>'{}')::uuid from test.state where key='session1'),false);
select test.denied($q$select public.save_activity('Changed','',array[(select id from public.classes where slug='poraque')],'[{}]'::jsonb,false,(select (value#>>'{}')::uuid from test.state where key='activity1'))$q$,'published history cannot be edited');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session1'),'open',clock_timestamp()+interval '1 minute');
reset role;
select test.ok((select count(*)>=7 from public.audit_events),'sensitive administrative actions are audited');
select test.ok(not exists(select 1 from public.audit_events where details::text like '%credential%' or details::text like '%token%'),'audit details contain no credentials or tokens');
update app_private.team_sessions set expires_at=now()-interval '1 second';
set local role anon;
select test.denied($q$select public.team_history((select value->>'token' from test.state where key='recovered'))$q$,'expired bearer cannot recover history');
reset role;
set constraints all immediate;
rollback;
